callGraph.callee:
syncConnectionsApi
      .list()
      .then((connections) => {
        if (!cancelled) setProjectConnections(connections);
      })
      .catch((err) => {
        if (!cancelled) {
          setProjectConnectionsError(
            err instanceof Error ? err.message : String(err)
          );
        }
      })
      .finally

skillsHubRaw
        .readSkill(skillName)
        .then(async (content) => {
          await skillEditorHook.startEdit(skill, content);
          setExtensionSelectedId(null);
          openWizard(WIZARD_IDS.SKILL_EDIT, skillName);
        })
        .catch

readRule(
      selectedMarkdownRule.name,
      selectedMarkdownRule.source,
      selectedMarkdownRule.repoPath
    )
      .then((content) => {
        if (!cancelled)
          setLoadedRuleContent({
            ruleName: selectedMarkdownRule.name,
            content,
          });
      })
      .catch
